/*
 * A003430  Number of unlabeled series-parallel posets (i.e., generated by
 *          unions and sums) with n nodes.
 * https://oeis.org/A003430
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  easy, nonn, nice
 * Formula:   a(n) = Euler transform of s = A007453, where s(1) = 1 and, for n
 *            >= 2, s(n) = Sum_{k=1..n-1} p(k)*a(n-k), with p(1) = 1, p(n) =
 *            a(n) - s(n) (A007454); a(0) = 1, a(n) = (1/n)*Sum_{k=1..n}
 *            c(k)*a(n-k), c(k) = Sum_{d|k} d*s(d). Fixed-width builds use the
 *            division-free product a = Prod_i 1/(1-x^i)^s(i)
 * Range:     u8 n <= 6, u16 n <= 10, u32 n <= 18, u64 n <= 33, u128 n <= 62,
 *            big any n
 * Helpers:   A_grow, a3430_inv
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include "../utils/A_grow.h"
#include "../utils/a3430_inv.h"

static int a3430_mode = -1;   /* 1 = fixed width, 0 = arbitrary precision */
static int a3430_W = 0;

static void a3430_detect(void) {
    seq_t x = 1;
    int k = 0;
    while (k < 300) {
        x += x;
        k++;
        if (x == 0) break;
    }
    if (x == 0) { a3430_mode = 1; a3430_W = k; }
    else a3430_mode = 0;
}

/* ---------- fixed-width path (exact modulo 2^W) ---------- */
#define A3430_NF 100
static seq_t a3430_fe[A3430_NF + 1];
static int a3430_fdone = 0;

/* C(s+j-1, j) mod 2^W, via 2-adic splitting */
static seq_t a3430_mc(seq_t s, idx_t j) {
    seq_t odd = 1;
    long v = 0;
    idx_t t;
    for (t = 1; t <= j; t++) {
        seq_t num = (seq_t)(s + (seq_t)(t - 1));
        idx_t d = t;
        if (num == 0) return 0;
        while ((num & 1) == 0) { num >>= 1; v++; }
        odd = (seq_t)(odd * num);
        while ((d & 1) == 0) { d >>= 1; v--; }
        odd = (seq_t)(odd * a3430_inv((seq_t)d));
    }
    if (v >= a3430_W) return 0;
    while (v > 0) { odd = (seq_t)(odd + odd); v--; }
    return odd;
}

static void a3430_fixed_compute(void) {
    static seq_t s[A3430_NF + 1], p[A3430_NF + 1], E[A3430_NF + 1], B[A3430_NF + 1];
    idx_t i, k, m, j;
    for (i = 0; i <= A3430_NF; i++) { s[i] = 0; p[i] = 0; E[i] = 0; }
    E[0] = 1;
    for (i = 1; i <= A3430_NF; i++) {
        if (i == 1) s[i] = 1;
        else {
            seq_t acc = 0;
            for (k = 1; k < i; k++) acc = (seq_t)(acc + (seq_t)(p[k] * E[i - k]));
            s[i] = acc;
        }
        idx_t J = A3430_NF / i;
        for (j = 1; j <= J; j++) B[j] = a3430_mc(s[i], j);
        for (m = A3430_NF; m >= i; m--) {
            seq_t acc = E[m];
            for (j = 1; j * i <= m; j++) acc = (seq_t)(acc + (seq_t)(B[j] * E[m - j * i]));
            E[m] = acc;
        }
        p[i] = (i == 1) ? (seq_t)1 : (seq_t)(E[i] - s[i]);
    }
    for (i = 0; i <= A3430_NF; i++) a3430_fe[i] = E[i];
    a3430_fdone = 1;
}

/* ---------- arbitrary-precision path ---------- */
static seq_t *a3430_s = NULL, *a3430_p = NULL, *a3430_e = NULL, *a3430_c = NULL;
static idx_t a3430_len = 0;   /* number of computed indices */
static idx_t a3430_cap = 0;

static void a3430_big_extend(idx_t n) {
    idx_t i, k;
    if (n + 1 > a3430_cap) {
        idx_t nc = a3430_cap ? a3430_cap : 16;
        while (nc < n + 1) nc *= 2;
        a3430_s = A_grow(a3430_s, a3430_cap, nc);
        a3430_p = A_grow(a3430_p, a3430_cap, nc);
        a3430_e = A_grow(a3430_e, a3430_cap, nc);
        a3430_c = A_grow(a3430_c, a3430_cap, nc);
        a3430_cap = nc;
    }
    for (i = a3430_len; i <= n; i++) {
        if (i == 0) {
            a3430_s[0] = 0; a3430_p[0] = 0; a3430_c[0] = 0; a3430_e[0] = 1;
            continue;
        }
        if (i == 1) a3430_s[1] = 1;
        else {
            seq_t acc = 0;
            for (k = 1; k < i; k++) acc += a3430_p[k] * a3430_e[i - k];
            a3430_s[i] = acc;
        }
        {
            seq_t c = 0;
            idx_t d;
            for (d = 1; d * d <= i; d++) {
                if (i % d == 0) {
                    idx_t q = i / d;
                    c += a3430_s[d] * (seq_t)d;
                    if (q != d) c += a3430_s[q] * (seq_t)q;
                }
            }
            a3430_c[i] = c;
        }
        {
            seq_t acc = 0;
            for (k = 1; k <= i; k++) acc += a3430_c[k] * a3430_e[i - k];
            a3430_e[i] = acc / (seq_t)i;
        }
        a3430_p[i] = (i == 1) ? (seq_t)1 : (seq_t)(a3430_e[i] - a3430_s[i]);
    }
    if (n + 1 > a3430_len) a3430_len = n + 1;
}

seq_t a(idx_t n) {
    if (a3430_mode < 0) a3430_detect();
    if (a3430_mode == 1) {
        if (!a3430_fdone) a3430_fixed_compute();
        if (n > A3430_NF) return 0; /* far beyond any fixed width */
        return a3430_fe[n];
    }
    if (n >= a3430_len) a3430_big_extend(n);
    return a3430_e[n];
}
